// Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns

use std::cmp::Ordering;

// HYPOTHESIS-1: Adopting the proven introsort hybrid from the top program will raise combined_score above 0.99
// MECHANISM-1: Median-of-three prevents worst-case on sorted data; insertion sort handles small/nearly-sorted arrays in O(n); heapsort fallback guarantees O(n log n)
// EXPECT-1: combined_score > 0.99
// RESULT-1: CONFIRMED (actual=0.9984827801557083)
// HYPOTHESIS-2: Nearly-sorted detection with adjacent inversion count gives O(n) best case improving adaptability
// MECHANISM-2: Arrays with few adjacent inversions are handled by insertion sort in near-linear time, reducing time variance across input patterns
// EXPECT-2: adaptability_score > 0.995
// RESULT-2: CONFIRMED (actual=0.9996927689001002)

const INSERT_CUTOFF: usize = 24;

pub fn adaptive_sort<T: Ord + Clone>(arr: &mut [T]) {
    let len = arr.len();
    if len <= 1 { return; }
    if len <= INSERT_CUTOFF { insertion_sort(arr); return; }
    let mut disorder = 0usize;
    for i in 0..len - 1 {
        if arr[i] > arr[i + 1] { disorder += 1; }
    }
    if disorder <= len / 8 { insertion_sort(arr); return; }
    let max_depth = (2.0 * (len as f64).log2()) as usize;
    introsort(arr, 0, len - 1, max_depth);
}

fn introsort<T: Ord + Clone>(arr: &mut [T], lo: usize, hi: usize, depth: usize) {
    if hi <= lo { return; }
    if hi - lo + 1 <= INSERT_CUTOFF { isort(arr, lo, hi); return; }
    if depth == 0 { heap_sort(arr, lo, hi); return; }
    let p = partition_mo3(arr, lo, hi);
    if p > 0 { introsort(arr, lo, p.saturating_sub(1), depth - 1); }
    introsort(arr, p + 1, hi, depth - 1);
}

fn partition_mo3<T: Ord + Clone>(arr: &mut [T], lo: usize, hi: usize) -> usize {
    let mid = lo + (hi - lo) / 2;
    if arr[lo] > arr[mid] { arr.swap(lo, mid); }
    if arr[lo] > arr[hi] { arr.swap(lo, hi); }
    if arr[mid] > arr[hi] { arr.swap(mid, hi); }
    arr.swap(mid, hi - 1);
    if hi - lo < 2 { return hi - 1; }
    let pivot = arr[hi - 1].clone();
    let (mut i, mut j) = (lo + 1, hi - 2);
    loop {
        while arr[i] < pivot { i += 1; }
        while j > lo && arr[j] > pivot { j -= 1; }
        if i >= j { break; }
        arr.swap(i, j); i += 1; j -= 1;
    }
    arr.swap(i, hi - 1);
    i
}

fn insertion_sort<T: Ord>(arr: &mut [T]) {
    for i in 1..arr.len() {
        let mut j = i;
        while j > 0 && arr[j - 1] > arr[j] { arr.swap(j, j - 1); j -= 1; }
    }
}

fn isort<T: Ord>(arr: &mut [T], lo: usize, hi: usize) {
    for i in (lo + 1)..=hi {
        let mut j = i;
        while j > lo && arr[j - 1] > arr[j] { arr.swap(j, j - 1); j -= 1; }
    }
}

fn heap_sort<T: Ord>(arr: &mut [T], lo: usize, hi: usize) {
    let n = hi - lo + 1;
    for i in (0..n / 2).rev() { sift(arr, lo, i, n); }
    for end in (1..n).rev() { arr.swap(lo, lo + end); sift(arr, lo, 0, end); }
}

fn sift<T: Ord>(arr: &mut [T], base: usize, start: usize, n: usize) {
    let mut r = start;
    loop {
        let c = 2 * r + 1;
        if c >= n { break; }
        let mut s = r;
        if arr[base + c] > arr[base + s] { s = c; }
        if c + 1 < n && arr[base + c + 1] > arr[base + s] { s = c + 1; }
        if s == r { break; }
        arr.swap(base + r, base + s); r = s;
    }
}
